// One item per role-family query, so JSearch/Remotive each run once per
// role instead of one query string trying to cover ops + PM + automation.
// Edit the "target_job_queries" field (comma-separated) in the Config node to add/remove roles.
const queries = ($('Config').first().json.target_job_queries || 'operations manager')
  .split(',')
  .map((q) => q.trim())
  .filter(Boolean);

return queries.map((query) => ({ json: { query } }));

// RemoteOK's API takes no search parameter — it returns its whole recent
// feed — so filter here against the same role queries the other sources
// use. Without this, every listing would go on to cost an Anthropic call.
const queries = ($('Config').first().json.target_job_queries || '')
  .split(',')
  .map((q) => q.trim().toLowerCase())
  .filter(Boolean);

// n8n may split a top-level JSON array response into one item per element,
// or hand back a single item holding the array. Handle both.
const rows = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j)) rows.push(...j);
  else if (Array.isArray(j.data)) rows.push(...j.data);
  else rows.push(j);
}

const output = [];

for (const row of rows) {
  // The feed's first element is RemoteOK's legal notice, not a job.
  if (!row || row.legal || !(row.position || row.title)) continue;

  const haystack = [row.position, row.title, row.company, (row.tags || []).join(' ')]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

  const matches =
    queries.length === 0 ||
    queries.some((q) => q.split(/\s+/).every((word) => haystack.includes(word)));

  if (!matches) continue;

  output.push({ json: { source: 'remoteok', raw: row } });
}

return output;

// Runs once per role query (see "Role Queries"), so flatten every input
// item's jobs array, not just the first.
const output = [];

for (const item of $input.all()) {
  const jobs = item.json.jobs || [];
  for (const job of jobs) {
    output.push({ json: { source: 'remotive', raw: job } });
  }
}

return output;

// Runs once per role query (see "Role Queries"), so this must flatten
// every input item's results, not just the first.
const output = [];

for (const item of $input.all()) {
  const jobs = item.json.data || [];
  for (const job of jobs) {
    output.push({ json: { source: 'jsearch', raw: job } });
  }
}

return output;

// Edit this list, or replace with an Airtable "Target Companies" lookup later.
const TARGET_COMPANIES = [
  // { company: 'stripe', ats: 'greenhouse' },
  // { company: 'netflix', ats: 'lever' },
];

const results = [];

for (const target of TARGET_COMPANIES) {
  const { company, ats } = target;
  let url;

  if (ats === 'greenhouse') {
    url = `https://boards-api.greenhouse.io/v1/boards/${company}/jobs?content=true`;
  } else if (ats === 'lever') {
    url = `https://api.lever.co/v0/postings/${company}?mode=json`;
  } else if (ats === 'ashby') {
    url = `https://api.ashbyhq.com/posting-api/job-board/${company}`;
  } else {
    continue;
  }

  let response;
  try {
    response = await this.helpers.httpRequest({
      method: 'GET',
      url,
      json: true,
      ignoreHttpStatusErrors: true,
    });
  } catch (err) {
    continue;
  }

  if (!response) continue;

  if (ats === 'greenhouse') {
    for (const job of response.jobs || []) {
      results.push({ json: { source: 'greenhouse', company, raw: job } });
    }
  } else if (ats === 'lever') {
    const jobs = Array.isArray(response) ? response : [];
    for (const job of jobs) {
      results.push({ json: { source: 'lever', company, raw: job } });
    }
  } else if (ats === 'ashby') {
    for (const job of response.jobs || []) {
      results.push({ json: { source: 'ashby', company, raw: job } });
    }
  }
}

return results;

// Employer careers pages to watch, for companies that don't use a
// supported ATS. Add ONLY pages you have checked are OK to read
// automatically: visit thesite.com/robots.txt and skim their terms for
// "automated", "scraping", "crawl".
//
// Do NOT put large commercial job boards here (JobStreet, Indeed,
// LinkedIn, etc.) — their terms ban automated collection and they run bot
// detection, so it is the same ToS/ban risk this project ruled out on
// day one.
const CAREERS_PAGES = [
  { company: 'Somewhere', url: 'https://somewhere.com/jobs' },
  // { company: 'Example VA Agency', url: 'https://example.com/careers' },
];

const results = [];

for (const page of CAREERS_PAGES) {
  let html;
  try {
    html = await this.helpers.httpRequest({
      method: 'GET',
      url: page.url,
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; JobWatcher/1.0)' },
      ignoreHttpStatusErrors: true,
    });
  } catch (err) {
    continue;
  }

  if (typeof html !== 'string' || !html.trim()) continue;

  const text = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 6000);

  // Too little text usually means the listings are rendered by JavaScript,
  // which a plain fetch can't see. Skip rather than send junk to the model.
  if (text.length < 100) continue;

  results.push({ json: { company: page.company, url: page.url, page_text: text } });
}

return results;

const responses = $input.all();
const pages = $('Fetch Careers Pages').all();
const output = [];

for (let i = 0; i < responses.length; i++) {
  const text = responses[i].json.content?.[0]?.text || '';
  const page = pages[i]?.json || {};

  let jobs;
  try {
    jobs = JSON.parse(text);
  } catch (err) {
    const match = text.match(/\[[\s\S]*\]/);
    try {
      jobs = match ? JSON.parse(match[0]) : [];
    } catch (err2) {
      jobs = [];
    }
  }

  if (!Array.isArray(jobs)) continue;

  for (const job of jobs) {
    if (!job || !job.title) continue;
    output.push({
      json: {
        source: 'careers_page',
        company: page.company || '',
        raw: {
          title: job.title,
          location: job.location || '',
          description: job.description || '',
          url: job.url || page.url || '',
        },
      },
    });
  }
}

return output;

// Field names below follow each API's documented shape, with fallbacks so a
// single renamed field doesn't blank out a whole listing.
function normalizeRemoteOK(raw) {
  return {
    title: raw.position || raw.title || '',
    company: raw.company || '',
    location: raw.location || 'Remote',
    url: raw.url || raw.apply_url || '',
    description: raw.description || '',
    posted_at: raw.date || '',
  };
}

function normalizeRemotive(raw) {
  return {
    title: raw.title || '',
    company: raw.company_name || raw.company || '',
    location: raw.candidate_required_location || 'Remote',
    url: raw.url || '',
    description: raw.description || '',
    posted_at: raw.publication_date || '',
  };
}

function normalizeJSearch(raw) {
  const location = [raw.job_city, raw.job_state, raw.job_country].filter(Boolean).join(', ');
  return {
    title: raw.job_title || '',
    company: raw.employer_name || '',
    location: location || (raw.job_is_remote ? 'Remote' : ''),
    url: raw.job_apply_link || raw.job_google_link || '',
    description: raw.job_description || '',
    posted_at: raw.job_posted_at_datetime_utc || '',
  };
}

function normalizeGreenhouse(raw, company) {
  return {
    title: raw.title || '',
    company,
    location: raw.location?.name || '',
    url: raw.absolute_url || '',
    description: raw.content || '',
    posted_at: raw.updated_at || '',
  };
}

function normalizeLever(raw, company) {
  return {
    title: raw.text || '',
    company,
    location: raw.categories?.location || '',
    url: raw.hostedUrl || '',
    description: raw.descriptionPlain || raw.description || '',
    posted_at: raw.createdAt ? new Date(Number(raw.createdAt)).toISOString() : '',
  };
}

function normalizeAshby(raw, company) {
  return {
    title: raw.title || '',
    company,
    location: raw.location || '',
    url: raw.jobUrl || raw.applyUrl || '',
    description: raw.descriptionPlain || raw.description || '',
    posted_at: raw.publishedAt || '',
  };
}

// Careers-page jobs arrive already extracted by the model, so this is a
// pass-through. posted_at is left blank — careers pages rarely state it.
function normalizeCareersPage(raw, company) {
  return {
    title: raw.title || '',
    company,
    location: raw.location || '',
    url: raw.url || '',
    description: raw.description || '',
    posted_at: '',
  };
}

const output = [];

for (const item of $input.all()) {
  const { source, company, raw } = item.json;
  let normalized;

  switch (source) {
    case 'remoteok': normalized = normalizeRemoteOK(raw); break;
    case 'remotive': normalized = normalizeRemotive(raw); break;
    case 'jsearch': normalized = normalizeJSearch(raw); break;
    case 'greenhouse': normalized = normalizeGreenhouse(raw, company); break;
    case 'lever': normalized = normalizeLever(raw, company); break;
    case 'ashby': normalized = normalizeAshby(raw, company); break;
    case 'careers_page': normalized = normalizeCareersPage(raw, company); break;
    default: continue;
  }

  if (!normalized.title || !normalized.company || !normalized.url) continue;

  output.push({ json: { ...normalized, source } });
}

return output;

const crypto = require('crypto');

return $input.all().map((item) => {
  const { company, title, location } = item.json;

  const key = [company, title, location]
    .map((v) => String(v || '').trim().toLowerCase())
    .join('|');

  const dedupe_hash = crypto.createHash('sha256').update(key).digest('hex');

  return { json: { ...item.json, dedupe_hash } };
});

const existingHashes = new Set(
  $('Airtable: Get Existing Hashes')
    .all()
    .map((item) => item.json['Job ID'])
    .filter(Boolean)
);

// Multiple role queries (ops/PM/automation) can surface the same posting
// in one run — dedupe against Airtable AND within this run's own items.
const seenThisRun = new Set();
const output = [];

for (const item of $input.all()) {
  const hash = item.json.dedupe_hash;
  if (existingHashes.has(hash) || seenThisRun.has(hash)) continue;
  seenThisRun.add(hash);
  output.push(item);
}

return output;

const response = $input.item.json;
const text = response.content?.[0]?.text || '';

let parsed;
try {
  parsed = JSON.parse(text);
} catch (err) {
  const match = text.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { score: 0, reason: 'Could not parse model output' };
}

const job = $('Filter New Jobs').item.json;

return {
  json: {
    ...job,
    fit_score: Number(parsed.score) || 0,
    fit_reason: String(parsed.reason || '').slice(0, 500),
  },
};

const response = $input.item.json;
const letter = response.content?.[0]?.text?.trim() || '';
const job = $('Parse Fit Score').item.json;

return {
  json: {
    ...job,
    cover_letter: letter,
    status: 'pending',
  },
};

const job = $('Parse Fit Score').item.json;

return {
  json: {
    ...job,
    cover_letter: '',
    status: 'skipped',
  },
};

const jobs = $input.first().json.data || [];

if (jobs.length === 0) {
  return [{ json: { digest_text: '' } }];
}

const lines = jobs.map((job, i) => {
  return [
    `*${i + 1}. ${job.title}* — ${job.company}`,
    `   Fit: ${job.fit_score}/100 — ${job.fit_reason}`,
    `   ${job.location || 'Location not listed'} | ${job.source}`,
    `   <${job.url}|Open posting>`,
  ].join('\n');
});

const digest_text = [
  `*${jobs.length} new application${jobs.length === 1 ? '' : 's'} ready for review* :inbox_tray:`,
  '',
  ...lines,
  '',
  'Cover letters are drafted and rows are logged as `pending` in Airtable. Review, then submit.',
].join('\n');

return [{ json: { digest_text, job_count: jobs.length } }];
